function transfer([action, answer, feedback, levels]) {
  const [exemplary, proficient, developing, beginning] = levels;
  return {
    action,
    answer,
    feedback,
    reasoning: [
      '先按案例记录区分所描述群体与目标群体。',
      '使用该案例的计数、分类状态和时点完成本项判断，不套用维修案例的数值。',
    ],
    levels: { exemplary, proficient, developing, beginning },
  };
}
function requirement(stage, index, final = false) {
  const [exemplary, proficient, developing, beginning] = stage.levels;
  return {
    id: `proportion-${index + 1}`,
    weight: final ? 20 : 100,
    label: stage.label,
    action: stage.action,
    answer: stage.answer,
    reasoning: stage.reasoning,
    feedback: stage.feedback,
    levels: { exemplary, proficient, developing, beginning },
    guided: stage.guided,
    examples: { partial: stage.partial, misconception: stage.wrong, alternative: stage.alternative },
    transfer: transfer((final ? bookPractice : seedPractice)[index]),
  };
}
